func updateUI() {
    // already running on the main thread
    DispatchQueue.main.sync {
        label.text = "Done"
    }
}

let semaphore = DispatchSemaphore(value: 0)
queue.async {
    doSetup()
    semaphore.signal()
}
queue.sync {
    semaphore.wait() // called on `queue` itself, a serial queue
}

actor Account {
    private var balance = 100

    func withdraw(_ amount: Int) async {
        guard balance >= amount else { return }
        await logAttempt()
        balance -= amount
    }
}

func fetchAll(_ urls: [URL]) async throws -> [Data] {
    try await withThrowingTaskGroup(of: Data.self) { group in
        for url in urls {
            group.addTask { try await fetch(url) }
        }
        var results: [Data] = []
        for try await data in group {
            results.append(data)
        }
        return results
    }
}

func load() async throws -> Data {
    try await withCheckedThrowingContinuation { continuation in
        legacyLoad { result in
            continuation.resume(with: result)
        }
        legacyLoadFallback { result in
            continuation.resume(with: result)
        }
    }
}

final class Counter {
    var value = 0
}

let counter = Counter()
Task {
    counter.value += 1
}

@MainActor
final class ReportViewModel {
    func generate() async {
        let rows = fetchRowsSynchronously() // blocking, CPU-heavy, no internal await
        self.rows = rows
    }
}
